def solve():
    mcap_a = Q(P["MCAP_A"])
    rev_b = Q(P["REV_B"])
    rev_d = Q(P["REV_D"])
    thresh = Q(P["THRESH"])
    capex_b = Q(P["CAPEX_B"])
    exempt_min = Q(P["EXEMPT_MIN"])
    cap_mult = Q(P["CAP_MULT"])

    issuers = {
        "A": {"mcap": mcap_a, "rev": Q(0), "capex": Q(0)},
        "B": {"mcap": Q(300), "rev": rev_b, "capex": capex_b},
        "C": {"mcap": Q(250), "rev": Q(5), "capex": Q(0)},
        "D": {"mcap": Q(200), "rev": rev_d, "capex": Q(12)},
        "E": {"mcap": Q(150), "rev": Q(0), "capex": Q(0)},
    }

    # Exclusion screen with transition exemption
    retained = []
    excluded = []
    for name, d in issuers.items():
        breach = d["rev"] > thresh
        exempt = d["capex"] >= exempt_min
        if breach and not exempt:
            excluded.append(name)
        else:
            retained.append(name)

    n = len(retained)
    if n == 0:
        raise ValueError("no retained issuers")

    total_mcap = sum(issuers[k]["mcap"] for k in retained)
    weights = {k: issuers[k]["mcap"] / total_mcap * 100 for k in retained}

    cap_level = cap_mult * (Q(100) / n)

    # Single-pass capping
    cut = {}
    uncut = {}
    excess = Q(0)
    for k in retained:
        w = weights[k]
        if w > cap_level:
            excess += w - cap_level
            cut[k] = cap_level
        else:
            uncut[k] = w

    final_w = dict(cut)
    uncut_total = sum(uncut.values())
    if excess > 0:
        if uncut_total == 0:
            raise ValueError("no recipients for redistribution")
        for k, w in uncut.items():
            final_w[k] = w + excess * (w / uncut_total)
    else:
        for k, w in uncut.items():
            final_w[k] = w

    largest = max(final_w.values())
    c_final = final_w.get("C", Q(0))

    return {
        "final": c_final,
        "excluded_count": Q(len(excluded)),
        "cap_level": cap_level,
        "redistributed_excess": excess,
        "largest_final_weight": largest,
    }
